-- PS-005.4 endurece la consistencia de endpoints tras detectar semántica NULL en PostgreSQL CHECK.
-- Alcance: añade una restricción a portal.client_connection_profiles; no modifica migraciones previas.
-- Reversión de código: volver a la versión anterior no elimina este CHECK ni los endpoints guardados.
ALTER TABLE "portal"."client_connection_profiles" ADD CONSTRAINT "client_connection_profiles_complete_endpoint_check" CHECK (("portal"."client_connection_profiles"."destination_hostname" IS NULL AND "portal"."client_connection_profiles"."destination_port" IS NULL AND "portal"."client_connection_profiles"."gateway_hostname" IS NULL AND "portal"."client_connection_profiles"."gateway_port" IS NULL AND "portal"."client_connection_profiles"."gateway_fingerprint" IS NULL) OR ("portal"."client_connection_profiles"."profile_type" = 'MYSQL_TCP' AND "portal"."client_connection_profiles"."destination_hostname" IS NOT NULL AND btrim("portal"."client_connection_profiles"."destination_hostname") <> '' AND "portal"."client_connection_profiles"."destination_port" IS NOT NULL AND "portal"."client_connection_profiles"."destination_port" BETWEEN 1 AND 65535 AND "portal"."client_connection_profiles"."gateway_hostname" IS NULL AND "portal"."client_connection_profiles"."gateway_port" IS NULL AND "portal"."client_connection_profiles"."gateway_fingerprint" IS NULL) OR ("portal"."client_connection_profiles"."profile_type" = 'MYSQL_SSH' AND "portal"."client_connection_profiles"."destination_hostname" IS NOT NULL AND btrim("portal"."client_connection_profiles"."destination_hostname") <> '' AND "portal"."client_connection_profiles"."destination_port" IS NOT NULL AND "portal"."client_connection_profiles"."destination_port" BETWEEN 1 AND 65535 AND "portal"."client_connection_profiles"."gateway_hostname" IS NOT NULL AND btrim("portal"."client_connection_profiles"."gateway_hostname") <> '' AND "portal"."client_connection_profiles"."gateway_port" IS NOT NULL AND "portal"."client_connection_profiles"."gateway_port" BETWEEN 1 AND 65535 AND "portal"."client_connection_profiles"."gateway_fingerprint" IS NOT NULL AND "portal"."client_connection_profiles"."gateway_fingerprint" ~ '^SHA256:[A-Za-z0-9+/]{43}$'));
